    struct tile_t {
        size_t src;
        size_t csize;
        size_t dst;
        size_t size;
    };

    struct stream_t {
        size_t total = 0;
        std::vector<tile_t> tiles;
    };

    struct stats_t {
        size_t blocks = 0;
        size_t stored = 0;
        size_t fixed = 0;
        size_t dynamic = 0;
        size_t literals = 0;
        size_t matches = 0;
        size_t match_bytes = 0;
        size_t max_match = 0;
        size_t long_matches = 0;
        size_t rounds = 0;
        size_t long_codes = 0;
        size_t dep_matches = 0;
        size_t dep_rounds = 0;
        size_t dist_hist[5] = {};
        size_t long_dist_hist[5] = {};
        size_t len_hist[16] = {};
        size_t dlen_hist[16] = {};
        size_t slow_rounds[3] = {};
        size_t lit_rounds = 0;
        size_t far_hist[8] = {};
    };

    extern int g_ring_check;
    extern size_t g_trace;
    bool is_gdeflate(const uint8_t* p, size_t n);
    bool parse(const uint8_t* p, size_t n, stream_t& s, std::string& err);
    bool parse_head(const uint8_t* p, size_t n, size_t stream_size, stream_t& s, std::string& err);
